import os,pathlib
def provision(mon,entity,pool,namespace,keyring):
    caps=['mon','profile rbd','osd','profile rbd pool='+pool+' namespace='+namespace]
    credentials=mon('auth get-or-create',entity=entity,caps=caps);key=credentials[0]['key'];path=pathlib.Path(keyring)
    path.write_text('['+entity+']\n key = '+key+'\n');os.chmod(path,0o600)
    return {'entity':entity,'keyring':str(path),'pool':pool,'namespace':namespace,'default_admin_changed':False}
def rotate(mon,old_entity,new_entity,pool,namespace,keyring,probe):
    provision(mon,new_entity,pool,namespace,keyring)
    if probe(new_entity,keyring)is not True:raise ValueError('new application readiness failed; retain old identity')
    mon('auth del',entity=old_entity)
    return {'new_entity':new_entity,'old_entity_removed':True,'fresh_auth_required':True,'existing_session_revocation_guaranteed':False}

